-- 09_insertion_periode_6.sql - Portrait de l'Âme (Périodes 6A et 6B)
-- ═══════════════════════════════════════════════════════════════════════════

INSERT INTO cycle_vie_soul_periods (
    period_number, polarity, date_start, date_end, period_name, period_title,
    description_general, traits_positifs, traits_vigilance, professions_favorables,
    sante_vigilance, pays_affinites, conseils, message_cosmique, is_active
) VALUES 
-- PÉRIODE 6A
(6, 'A', '08-22', '09-22', 'Les Stratèges', 'L''Âme Stratège Patiente',
E'L''une des caractéristiques remarquables de votre influence planétaire est votre persistance, votre patience et votre détermination. Vous êtes de ceux qui atteignent leurs buts à travers des étapes lentes, délibérées et prudentes, plutôt que par impulsion ou coups de chance.\n\nVos incarnations passées vous ont enseigné que les victoires durables se construisent pierre après pierre. Vous avez témoigné de l''effondrement des empires bâtis trop vite.\n\nVous êtes un(e) planificateur(trice) né(e). Rien n''est laissé au hasard dans votre vie. Vous vous êtes rendu compte que des plans logiques et cohérents sont le seul moyen d''atteindre vos buts.',
E'**La Patience Stratégique**\nVous savez attendre le moment parfait pour agir. Cette patience est votre arme secrète.\n\n**La Planification Méticuleuse**\nChaque étape de votre vie est pensée, calculée, optimisée.\n\n**L''Économie des Ressources**\nVous savez faire beaucoup avec peu. Cette frugalité vous protège.\n\n**La Persistance Inébranlable**\nLes obstacles ne vous arrêtent pas — ils vous ralentissent simplement.',
E'**La Rigidité Excessive**\nVotre planification peut parfois devenir une prison.\n\n**L''Avarice Émotionnelle**\nVotre économie peut s''étendre aux émotions et aux relations.\n\n**L''Isolement du Stratège**\nÀ force de tout calculer seul(e), vous pouvez vous couper des autres.',
E'**Les Métiers de la Stratégie**\n• Directeur financier ou comptable senior\n• Consultant(e) en stratégie d''entreprise\n• Gestionnaire de patrimoine\n• Analyste en investissements\n\n**Les Métiers de la Construction Durable**\n• Architecte ou ingénieur civil\n• Entrepreneur(se) dans l''immobilier\n• Gestionnaire de projets à long terme\n• Conservateur(trice) de musée ou d''archives',
E'• Problèmes de genoux et de jambes\n• Désordres intestinaux\n• Éruptions cutanées et formations osseuses\n• Mélancolie et états dépressifs\n• Accidents et chutes',
E'Votre âme résonne particulièrement avec :\n• La Grèce et ses temples anciens\n• L''Inde et sa sagesse millénaire\n• Cuba et les Antilles\n• L''Amérique du Sud et ses civilisations anciennes\n• La Palestine et le Proche-Orient',
E'1. **Gardez de la Flexibilité** — Les meilleurs plans incluent des marges pour l''imprévu.\n2. **Investissez dans les Relations** — Les personnes ne sont pas des pièces sur un échiquier.\n3. **Célébrez les Étapes** — N''attendez pas le but final pour apprécier le chemin.\n4. **Prenez Soin de Votre Mental** — La mélancolie guette les stratèges solitaires.',
E'Vous êtes venu(e) dans cette vie pour bâtir des fondations qui dureront des générations. Votre patience et votre planification sont des dons rares dans un monde de gratification instantanée. Mais n''oubliez pas que la vie est aussi un voyage à savourer, pas seulement une destination à atteindre.',
true),

-- PÉRIODE 6B
(6, 'B', '08-22', '09-22', 'Les Ambitieux', 'L''Âme Ambitieuse Méthodique',
E'L''ambition joue un rôle majeur dans votre vie et vous éclaire constamment vers une position ou un pouvoir supérieur. Vos incarnations passées vous ont donné le goût des hauteurs et la méthode pour les atteindre.\n\nVous possédez une grande persévérance et détermination à atteindre vos objectifs. Cette combinaison d''ambition et de méthode est rare et précieuse.\n\nVous êtes un(e) excellent(e) étudiant(e) des sciences physiques et fasciné(e) par les forces et pouvoirs secrets de la nature. Il y a quelque chose du scientifique occulte en vous.',
E'**L''Ambition Éclairée**\nVotre ambition n''est pas aveugle — elle est guidée par une vision claire.\n\n**La Pensée Analytique**\nVous déconstruisez les problèmes complexes en éléments simples.\n\n**La Fascination pour l''Occulte**\nVous avez une capacité naturelle à percevoir ce qui est caché aux autres.\n\n**La Persévérance Calculée**\nVous ne lâchez jamais prise, mais vous savez aussi quand changer de tactique.',
E'**La Froideur Relationnelle**\nVotre nature analytique peut parfois vous rendre distant(e).\n\n**L''Obsession du Contrôle**\nVous voulez maîtriser chaque variable, mais la vie comporte des imprévus.\n\n**La Solitude du Sommet**\nPlus vous montez, plus l''air se raréfie.',
E'**Les Métiers de la Science**\n• Chercheur(se) en sciences physiques ou chimie\n• Ingénieur(e) spécialisé(e)\n• Analyste de données ou statisticien(ne)\n• Inventeur(trice) ou développeur(se) de technologies\n\n**Les Métiers du Pouvoir Discret**\n• Conseiller(ère) stratégique de l''ombre\n• Directeur(trice) de recherche et développement\n• Gestionnaire de risques\n• Expert(e) en cybersécurité',
E'• Problèmes articulaires (genoux, jambes)\n• Désordres digestifs\n• États mélancoliques\n• Risques d''accidents et de chutes',
E'Comme vos proches cosmiques :\n• La Grèce et l''Inde\n• Cuba et l''Amérique du Sud\n• Les terres orientales du Proche-Orient',
E'1. **Cultivez la Chaleur Humaine** — Les relations ne se calculent pas comme des équations.\n2. **Acceptez l''Incertitude** — Le contrôle total est une illusion.\n3. **Partagez Vos Découvertes** — Le savoir s''enrichit par le partage.\n4. **Surveillez Votre Moral** — La mélancolie guette les esprits trop analytiques.',
E'Vous êtes venu(e) dans cette vie pour maîtriser les forces invisibles et les mettre au service de vos objectifs. Votre intelligence et votre méthode sont des outils puissants. Mais n''oubliez pas que le cœur a ses raisons que la raison ne connaît point.',
true);

SELECT '✅ PÉRIODE 6 (6A + 6B) INSÉRÉE' as status;
